'use strict';
/* Deterministic editorial recommendation engine — no network, no tracking, no prices invented. */
(function(scope){
 const tierNames={essential:'Essentielle',signature:'Signature',prestige:'Prestige'};
 const movementNames={quartz:'Quartz',automatic:'Automatique','eco-drive':'Solaire Eco-Drive'};
 const styleNames={sport:'Sport chic',classic:'Élégance classique',minimal:'Épuré',retro:'Vintage',statement:'Audacieux'};
 const allowed={tier:new Set(['all',...Object.keys(tierNames)]),movement:new Set(['all',...Object.keys(movementNames)]),style:new Set(['all',...Object.keys(styleNames)])};
 function choices(input){
  const v=input&&typeof input==='object'?input:{};
  return {tier:allowed.tier.has(v.tier)?v.tier:'all',style:allowed.style.has(v.style)?v.style:'all',movement:allowed.movement.has(v.movement)?v.movement:'all'};
 }
 function score(p,c,index){
  const details=[];
  let total=0,exact=0;
  if(c.tier!=='all'){if(p.tier===c.tier){total+=8;exact++;details.push('Gamme '+tierNames[p.tier])}else total-=3}
  if(c.style!=='all'){if(p.style===c.style){total+=7;exact++;details.push(styleNames[p.style])}else if((c.style==='classic'&&p.style==='minimal')||(c.style==='minimal'&&p.style==='classic')){total+=2}else total-=2}
  if(c.movement!=='all'){if(p.movement===c.movement){total+=7;exact++;details.push(movementNames[p.movement])}else total-=3}
  const selected=Number(c.tier!=='all')+Number(c.style!=='all')+Number(c.movement!=='all');
  return {product:p,score:total,matched:exact,criteria:selected,details,index};
 }
 function recommend(products,selection,limit=3){
  if(!Array.isArray(products))return [];
  const c=choices(selection),allEmpty=c.tier==='all'&&c.style==='all'&&c.movement==='all';
  const valid=products.filter(p=>p&&typeof p.id==='string'&&Object.hasOwn(tierNames,p.tier)&&Object.hasOwn(styleNames,p.style)&&Object.hasOwn(movementNames,p.movement));
  if(allEmpty){
    const preferred=['casio-mtp-1302','citizen-tsuyosa','tissot-prx-auto'];
    const selected=preferred.map(id=>valid.find(p=>p.id===id)).filter(Boolean);
    const remaining=valid.filter(p=>!selected.includes(p));
    return selected.concat(remaining).slice(0,Math.max(0,Math.min(15,limit))).map((p,i)=>({product:p,score:0,matched:0,criteria:0,details:['Choix de la rédaction'],index:i}));
  }
  return valid.map((p,i)=>score(p,c,i)).sort((a,b)=>b.matched-a.matched||b.score-a.score||a.index-b.index).slice(0,Math.max(0,Math.min(15,limit)));
 }
 scope.AtelierAdvisorEngine=Object.freeze({recommend,choices,tierNames,movementNames,styleNames});
})(globalThis);

/* Atelier Montres — editorial adviser / intentionally independent of external design assets */
.advisor-page{background:#f9f7f2}
.advisor-page .header{position:relative;z-index:10}
.advisor-page a[aria-current=page]{color:#e7cb9c}
.advisor-hero{background:#182b23;color:#f6f2e9;overflow:hidden}
.advisor-hero-layout{display:grid;grid-template-columns:minmax(0,1.06fr) minmax(0,.94fr);align-items:center;gap:25px;min-height:615px}
.advisor-hero-layout>div:first-child{padding:88px 0;position:relative;z-index:2}
.advisor-hero h1{font:400 clamp(59px,7.4vw,108px)/1.02 Georgia,serif;letter-spacing:-.06em;margin:0 0 27px;max-width:650px}
.advisor-hero h1 em{font-style:italic;color:#dec292}
.advisor-lead{max-width:570px;color:#d4ded5;font-size:16px;line-height:1.85;margin:0 0 31px}
.advisor-hero-frame{height:530px;position:relative;display:grid;place-items:center;isolation:isolate}
.advisor-hero-frame:before{content:"";position:absolute;inset:5% 0;background:radial-gradient(circle at 50% 45%,#335640b0,transparent 60%);z-index:-2}
.advisor-hero-ring{position:absolute;width:min(90%,420px);aspect-ratio:1;border:1px solid #dfbf8e45;border-radius:50%;box-shadow:0 0 0 48px #bca7790b;z-index:-1}
.advisor-hero-frame img{display:block;max-width:100%;width:min(93%,500px);max-height:92%;object-fit:contain;filter:drop-shadow(18px 27px 30px #080d0999)}
.advisor-hero-caption{position:absolute;bottom:24px;right:0;display:flex;flex-direction:column;align-items:flex-end;gap:3px;text-shadow:0 2px 10px #11251dbb}
.advisor-hero-caption span{color:#d9be92;letter-spacing:.19em;font-size:9px}
.advisor-hero-caption strong{font:400 17px Georgia,serif;letter-spacing:.1em}
.advisor-ticker{background:#eae4d9;border-bottom:1px solid #d9ccba}
.advisor-ticker .wrap{min-height:55px;display:flex;gap:20px;justify-content:space-between;align-items:center;flex-wrap:wrap;padding-top:12px;padding-bottom:12px}
.advisor-ticker span{color:#526354;font:700 10px system-ui,sans-serif;letter-spacing:.14em}
.advisor-custom{padding:98px 0 102px}
.advisor-section-top,.advisor-picks-heading{display:grid;grid-template-columns:1.1fr .9fr;gap:45px;align-items:end;margin-bottom:35px}
.advisor-section-top h2,.advisor-picks-heading h2,.advisor-knowledge h2{font:400 clamp(38px,4.8vw,66px)/1.14 Georgia,serif;letter-spacing:-.04em;margin:0}
.advisor-section-top>p{max-width:470px;color:#657369;font-size:14px;line-height:1.85;margin:0 0 6px}
.advisor-question{border:0;border-top:1px solid #ddd7cc;padding:34px 0 36px;margin:0}
.advisor-question legend{display:flex;gap:16px;align-items:center;float:left;width:100%;font:400 clamp(22px,3vw,33px)/1.2 Georgia,serif;letter-spacing:-.02em;padding:0;margin-bottom:4px;color:#1d3528}
.advisor-question legend:after{content:"";display:block;clear:both}
.advisor-step{display:inline-grid;place-items:center;width:38px;height:38px;border:1px solid #b7a17a;border-radius:50%;font:700 11px system-ui;color:#8f754e;letter-spacing:0;flex-shrink:0}
.advisor-question>p{clear:both;padding-top:6px;margin:0 0 18px;color:#667367;font-size:13px;line-height:1.7}
.advisor-options{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:11px}
.advisor-style{grid-template-columns:repeat(3,minmax(0,1fr))}
